(139,	'broadcast_quest_accepted_generic',	'Taking on %quest_link in %zone_name. Let’s go!',	0,	0,	'%zone_name에서 %quest_link 도전! 가즈아~',	'Je me lance dans %quest_link dans la région de %zone_name. C’est parti !',	'%quest_link in %zone_name angenommen. Los!',	'在%zone_name挑战%quest_link，走起！',	'在%zone_name挑戰%quest_link，走起！',	'Emprendiendo %quest_link en %zone_name. ¡Vamos!',	'Emprendiendo %quest_link en %zone_name. ¡Vamos!',	'Берусь за %quest_link в %zone_name. Вперёд!'),
